import numpy as np
from scipy import stats
from collections import defaultdict

MAX_DRIVERS = 4

def design(feats):
    # Check if any feature shows significant association with outcome
    p_values = []
    for fid in feats.ids:
        col = feats.column(fid)
        t_stat, p_val = stats.ttest_ind(feats.x[feats.y==1, col], feats.x[feats.y==0, col])
        p_values.append(p_val)

    # If all p-values are high, return empty design
    if all(p > 0.1 for p in p_values):
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Find features with p < 0.05
    significant_features = [fid for fid, p in zip(feats.ids, p_values) if p < 0.05]

    # Remove near-duplicates (correlated with |r| >= 0.6)
    correlated_pairs = set()
    for i, fid1 in enumerate(feats.ids):
        for j, fid2 in enumerate(feats.ids[i+1:], i+1):
            if abs(np.corrcoef(feats.x[:, feats.column(fid1)], feats.x[:, feats.column(fid2)])[0,1]) >= 0.6:
                correlated_pairs.add((fid1, fid2))

    # Build a graph to find connected components
    adj = defaultdict(set)
    for a, b in correlated_pairs:
        adj[a].add(b)
        adj[b].add(a)

    # Group correlated features together
    visited = set()
    clusters = []
    for fid in feats.ids:
        if fid not in visited:
            cluster = set()
            stack = [fid]
            while stack:
                f = stack.pop()
                if f not in visited:
                    visited.add(f)
                    cluster.add(f)
                    for neighbor in adj[f]:
                        if neighbor not in visited:
                            stack.append(neighbor)
            clusters.append(cluster)

    # For each cluster, select the one with highest effect size
    selected_features = set()
    for cluster in clusters:
        # Select the feature with highest absolute t-statistic
        best_fid = max(cluster, key=lambda fid: abs(stats.ttest_ind(
            feats.x[feats.y==1, feats.column(fid)], 
            feats.x[feats.y==0, feats.column(fid)])[0]))
        selected_features.add(best_fid)

    # Also add all significant features that aren't part of any cluster
    for fid in significant_features:
        if fid not in selected_features:
            selected_features.add(fid)

    # Use just the top 4 features by effect size as drivers
    top_features = sorted(selected_features, key=lambda fid: abs(stats.ttest_ind(
        feats.x[feats.y==1, feats.column(fid)], 
        feats.x[feats.y==0, feats.column(fid)])[0]), reverse=True)[:MAX_DRIVERS]

    if top_features:
        drivers = tuple(top_features)
        columns = tuple(selected_features)
        products = ()
        loadings = {fid: 1.0 for fid in top_features}
        return Design(drivers=drivers, columns=columns, products=products, loadings=loadings)
    else:
        return Design(drivers=(), columns=(), products=(), loadings={})
